; Asteroids Deluxe (astdelux2) - 6502 program, traced disassembly
; generated by m6502trace.py from astdelux2_dump.bin - do not hand-edit
;
; Control flow was walked from the hardware vectors.  Bytes the walk
; never reached are emitted as data, not as invented instructions.
;
; Comments to the right of an instruction, the blocks above a
; routine, and the ruled section titles are the ORIGINAL comments
; from Atari's source, carried across by nameroutines.py.  They
; were only attached where a stretch of source lined up with a
; stretch of this listing one instruction to one instruction, so
; each sits on the exact byte it was written about.
;
; Lines marked [note] are this project's own descriptions, added under
; labels where the source's comments are thin or absent (ROUTINE_NOTES
; in astdelux_config.py).  Everything else is Atari's.
;
; Reading the names: NAME is a routine or data label from the source.
; NAME_20 is that routine's local label 20$ - a branch target inside
; it, kept under its owner's name.  RTS.n and NAME_RTS.n are the
; source's shared `RTS` labels.  Lxxxx is an address the source does
; not name.  Packed message text is decoded into the gutter as
; "TEXT" (msgtext.py).
;
; The $4800-$57FF ROM holds BOTH 6502 code and DVG display-list data;
; the two are interleaved because TRIROT.MAC is `.ASECT` / `.=4800`.
; Data blocks below that the DVG actually draws are decoded as vector
; opcodes in astdelux_vecrom.asm - they are marked [DVG] here.
;
; Symbol names are the originals, from the Atari source archive
; (DSTDEC/EAROM/PG0123 + the DSTRD0 linker map), which documents
; exactly this revision.
;
; entry  $785C  NMI vector ($FFFA)
; entry  $7CD7  RESET vector ($FFFC)
; entry  $7CD7  IRQ/BRK vector ($FFFE)
; entry  $7A19  VGJMPL - builds a DVG JMPL word ($E000). Reads as `lsr / and
;               #$0F / ora #$E0` then falls into the shared tail at $7A1E,
;               exactly mirroring VGJSRL at $7A2A (`... ora #$C0`), which IS
;               called. No `jsr $7A19` exists anywhere in the image
; entry  $7A72  VGVCTR - the general vector emitter. Decodes cleanly for 64+
;               instructions from `ldx #$00 / lda XCOMP+1 / cmp #$80`. No
;               `jsr $7A72` exists in the image; the game emits vectors
;               through VGADD/VGSABS instead
;

;======================================================================
; $4800-$57FF   vector board ROM   036800 @ $4800, 036799 @ $5000
;======================================================================

;----------------------------------------------------------------------
; SPLIT TIPS ON COLLISION
;----------------------------------------------------------------------

SPLTTP:
; xrefs: $6F8D
; [note] Split the tips off a special-rock cluster on collision; frees the linked objects
4800:  B9 00 02    lda OBJ,y                    ; GET PIX CODE
4803:  29 3C       and #$3C                     ; ISOLATE LINK FIELD
4805:  4A          lsr a                        ; MAKE IT RELATIVE TO 0
4806:  4A          lsr a
4807:  AA          tax                          ; POINT TO OBJECT PARAMS
4808:  BD F8 02    lda SRTIME,x                 ; GET CONTROL BYTE
480B:  10 31       bpl SPLTTP_1                 ; NOT WAITING
480D:  86 1A       stx XT                       ; SAVE INDEX
480F:  A9 05       lda #$05                     ; POINTS
4811:  20 B2 48    jsr GPTS                     ; GIVE POINTS
4814:  20 6C 6D    jsr SEARCH                   ; LOOK FOR FREE ENTRY
4817:  EE E7 02    inc NROCKS                   ; ADD ANOTHER TO TOTAL
481A:  B9 00 02    lda OBJ,y                    ; GET PIX CODE AGAIN
481D:  48          pha                          ; SAVE IT
481E:  20 10 62    jsr CPYPOS                   ; COPY ALL PARAMATERS
4821:  68          pla                          ; (CPYPOS BLITZES 'OBJ')
4822:  9D 00 02    sta OBJ,x                    ; (SO PASS THE OLD PIX CODE
4825:  A9 00       lda #$00
4827:  99 00 02    sta OBJ,y                    ; CAUSE A BIG EXPLOSION
482A:  A6 1A       ldx XT                       ; RESTORE X

SPLTTP_3:
; xrefs: $483C
482C:  BD F8 02    lda SRTIME,x                 ; FREE ALL THE OBJECTS IN THE CLUSTER
482F:  10 1D       bpl SPLTTP_2                 ; DONE
4831:  48          pha                          ; SAVE INDEX
4832:  A9 7F       lda #$7F
4834:  9D F8 02    sta SRTIME,x                 ; RELEASE AS BIG OBJECT WITH MAX TIME
4837:  68          pla                          ; RETRIEVE INDEX
4838:  4A          lsr a                        ; COMPUTE THE LINK VALUE
4839:  29 0F       and #$0F                     ; MASK
483B:  AA          tax                          ; X NOW HAS LINK TO NEXT OBJECT
483C:  10 EE       bpl SPLTTP_3                 ; (ALWAYS)

SPLTTP_1:
; xrefs: $480B
483E:  4A          lsr a                        ; PUT SIZE BIT INTO CARRY
483F:  B0 10       bcs SPLTTP_4                 ; ITS A BIG ONE
4841:  A9 00       lda #$00
4843:  9D F8 02    sta SRTIME,x                 ; DE-ACTIVATE CONTROL BYTE
4846:  A9 20       lda #$20
4848:  20 B2 48    jsr GPTS                     ; GIVE 'EM 200 POINTS
484B:  20 A4 49    jsr DIASND                   ; GIVE SOUND FOR DIAMOND

SPLTTP_2:
; xrefs: $482F
484E:  A6 0E       ldx TEMP3                    ; RESTORE X
4850:  60          rts                          ; EXIT

SPLTTP_4:
; xrefs: $483F
4851:  A9 10       lda #$10                     ; GIVE 'EM 200
4853:  86 1A       stx XT                       ; SAVE X
4855:  20 B2 48    jsr GPTS
4858:  20 6C 6D    jsr SEARCH                   ; FIND A FREE ENTRY
485B:  20 10 62    jsr CPYPOS                   ; COPY POSITION PARAMETERS
485E:  EE E7 02    inc NROCKS                   ; ADD 1 TO TOTAL OBJECTS
4861:  EE FF 02    inc SPROCK                   ; ADD 1 TO SPECIAL COUNT
4864:  A5 1A       lda XT                       ; GET CONTROL BYTE INDEX
4866:  0A          asl a
4867:  0A          asl a
4868:  09 42       ora #$42                     ; SAY ITS A SPECIAL ROCK BUT A SMALL ONE
486A:  9D 00 02    sta OBJ,x
486D:  86 10       stx R0                       ; SAVE X
486F:  A6 1A       ldx XT                       ; POINT TO CONTROL BYTE
4871:  A9 7E       lda #$7E
4873:  9D F8 02    sta SRTIME,x
4876:  A5 79       lda ANGLE
4878:  69 20       adc #$20                     ; POINT IT AWAY APPROX 45 DEGREES
487A:  9D F1 02    sta SRANG,x
487D:  20 A7 48    jsr FREESR                   ; FIND A FREE SPECIAL ROCK ENTRY
4880:  86 1A       stx XT                       ; SAVE ENTRY POINTER
4882:  A6 10       ldx R0                       ; POINT TO OBJ
4884:  20 6E 6D    jsr SEARC1                   ; LOOK FOR NEXT FREE OBJ
4887:  20 10 62    jsr CPYPOS                   ; MOVE POSITION PARAMETERS
488A:  EE E7 02    inc NROCKS                   ; ADD 1 TO TOTAL OBJECT COUNT
488D:  A5 1A       lda XT                       ; GET LINK TO SPECIAL
488F:  0A          asl a
4890:  0A          asl a
4891:  09 42       ora #$42
4893:  9D 00 02    sta OBJ,x                    ; SELECT SPECIAL ROCK
4896:  A6 1A       ldx XT                       ; POINT TO SPECIAL CONTROLS
4898:  A9 7E       lda #$7E                     ; ACTIVATE OBJECT
489A:  9D F8 02    sta SRTIME,x
489D:  A5 79       lda ANGLE
489F:  E9 20       sbc #$20                     ; POINT AWAY APPROX 45 DEGREES
48A1:  9D F1 02    sta SRANG,x
48A4:  A6 0E       ldx TEMP3                    ; RESTORE X
48A6:  60          rts                          ; EXIT

FREESR:
; xrefs: $487D
; [note] Find a free special-rock control entry, 6 down to 0; $FF if none
48A7:  A2 06       ldx #$06                     ; MAXIMUM # OF SPECIAL ROCKS ALLOWED

FREESR_2:
; xrefs: $48AF
48A9:  BD F8 02    lda SRTIME,x                 ; FIND AN EMPTY SLOT
48AC:  F0 03       beq TRIROT_RTS.0             ; GOT ONE
48AE:  CA          dex
48AF:  10 F8       bpl FREESR_2                 ; KEEP LOOKING

TRIROT_RTS.0:
; xrefs: $48AC, $48B8
; placed by hand: TRIROT.MAC:214 `RTS.0: RTS`, FREESR's exit. A bare RTS matches at every RTS in the ROM, so the order prune drops it. DSTRD0.MAC has its own RTS.0 (placed at $669C as DSTRD0_RTS.0); qualified by module the same way
48B1:  60          rts

GPTS:
; xrefs: $4811, $4848, $4855
; [note] Award points for a hit, but not when the saucer made it
48B2:  A6 0E       ldx TEMP3
48B4:  F0 04       beq GPTS_1                   ; SHIP. GIVE POINTS
48B6:  E0 04       cpx #$04                     ; SHIP'S TORPEDOES?
48B8:  90 F7       bcc TRIROT_RTS.0             ; NO. NO POINTS

GPTS_1:
; xrefs: $48B4
48BA:  18          clc
48BB:  4C 60 6C    jmp POINTS                   ; GIVE POINTS

;----------------------------------------------------------------------
; ATTACK SHIP
;----------------------------------------------------------------------

ATTACK:
; xrefs: $679F
; [note] Steer special rock X toward the ship
48BE:  86 10       stx R0                       ; SAVE X
48C0:  A0 19       ldy #$19                     ; ASSUME WE WILL TRACK SHIP
48C2:  84 11       sty R1                       ; INIT R1 FOR LATER
48C4:  E6 19       inc R9                       ; COUNT ATTACKING ENEMY
48C6:  BD 00 02    lda OBJ,x                    ; GET PIX CODE
48C9:  4A          lsr a
48CA:  4A          lsr a
48CB:  29 0F       and #$0F
48CD:  AA          tax                          ; POINT TO CONTROL BYTE
48CE:  BC F8 02    ldy SRTIME,x                 ; GET CONTROL
48D1:  C0 04       cpy #$04                     ; TIMED OUT?
48D3:  90 1C       bcc ATTACK_2                 ; YEP. TRACK TO EDGE
48D5:  A5 76       lda FRAME
48D7:  29 0F       and #$0F                     ; TIME OUT ?
48D9:  D0 07       bne ATTACK_3                 ; NOT HERE
48DB:  98          tya                          ; GET TIME
48DC:  38          sec
48DD:  E9 02       sbc #$02                     ; TIME DOWN
48DF:  9D F8 02    sta SRTIME,x

ATTACK_3:
; xrefs: $48D9
48E2:  AD 19 02    lda SHPPIX                   ; SHIP VISIBLE?
48E5:  F0 02       beq ATTACK_7                 ; NOPE. FORCE A TIME OUT
48E7:  10 0A       bpl ATTACK_4                 ; VISIBLE BUT BLOWING UP

ATTACK_7:
; xrefs: $48E5
48E9:  98          tya                          ; GET CONTROL
48EA:  29 01       and #$01                     ; KEEP SIZE
48EC:  09 02       ora #$02                     ; AND A MINIMUM TIME (KEEPS IT .NE.)
48EE:  9D F8 02    sta SRTIME,x

ATTACK_2:
; xrefs: $48D3
48F1:  E6 11       inc R1                       ; TRACK ON SNOW FLAKE

ATTACK_4:
; xrefs: $48E7
48F3:  A4 11       ldy R1
48F5:  86 1A       stx XT                       ; SAVE X
48F7:  A6 10       ldx R0                       ; POINT TO POSITION PARAMETERS
48F9:  20 1A 4A    jsr CPUTD
48FC:  20 F5 49    jsr RTST                     ; DO RANGE
48FF:  85 13       sta R3                       ; SAVE X DIFFERENCE
4901:  A5 0C       lda TEMP2
4903:  85 12       sta R2
4905:  A5 11       lda R1
4907:  18          clc
4908:  69 21       adc #$21                     ; SKIP TO Y PARAMETERS
490A:  A8          tay
490B:  8A          txa
490C:  69 21       adc #$21
490E:  AA          tax
490F:  20 1A 4A    jsr CPUTD                    ; COMPUTE Y DISTANCE
4912:  20 F5 49    jsr RTST                     ; RANGE IT
4915:  20 2A 4A    jsr SCALER                   ; SCALE IT, GET ARCTAN
4918:  A6 1A       ldx XT                       ; RESTORE X
491A:  85 12       sta R2                       ; SAVE ANGLE
491C:  A0 19       ldy #$19
491E:  C4 11       cpy R1                       ; TRACKING ON SHIP?
4920:  D0 19       bne ATTACK_21                ; NO. ALWAYS TURN
4922:  49 80       eor #$80                     ; FLIP IT 180
4924:  E5 79       sbc ANGLE                    ; SEE HOW IT COMPARES WITH SHIP'S ANGLE
4926:  10 02       bpl ATTACK_20
4928:  49 FF       eor #$FF

ATTACK_20:
; xrefs: $4926
492A:  C9 10       cmp #$10                     ; DON'T TURN IF SHIP IS POINTING AT ENEMY
492C:  B0 0D       bcs ATTACK_21                ; GO AHEAD AND TURN
492E:  A5 12       lda R2                       ; GET ANGLE
4930:  FD F1 02    sbc SRANG,x
4933:  10 02       bpl ATTACK_22
4935:  49 FF       eor #$FF

ATTACK_22:
; xrefs: $4933
