;----------------------------------------------------------------------
; MULTIPLY
;----------------------------------------------------------------------

MULT:
; xrefs: $4980, $4993, $6908
; AT EXIT:
; (A)=PRODUCT (SIGNED)
; Y,R1,R2,R3 DESTROYED
49B3:  A8          tay                          ; SET CONDITION CODES
49B4:  10 05       bpl MULT_1
49B6:  49 FF       eor #$FF
49B8:  18          clc
49B9:  69 01       adc #$01

MULT_1:
; xrefs: $49B4
49BB:  85 12       sta R2
49BD:  A9 00       lda #$00                     ; INITIALIZE PRODUCT
49BF:  85 13       sta R3

MULT_5:
; xrefs: $49DB
49C1:  06 11       asl R1                       ; CHECK BIT
49C3:  B0 0D       bcs MULT_2                   ; ADD IT IN
49C5:  D0 12       bne MULT_3                   ; STILL SOME BITS LEFT

MULT_6:
; xrefs: $49DD
