49C9:  C0 00       cpy #$00                     ; TEST SIGN AND SET CARRY
49CB:  10 04       bpl MULT_4                   ; OK
49CD:  49 FF       eor #$FF                     ; NEGATE PRODUCT
49CF:  69 00       adc #$00

MULT_4:
; xrefs: $49CB
49D1:  60          rts

MULT_2:
; xrefs: $49C3
49D2:  A5 13       lda R3                       ; ACCUMULATE PRODUCT
49D4:  18          clc
49D5:  65 12       adc R2
49D7:  85 13       sta R3

MULT_3:
; xrefs: $49C5
