49DB:  D0 E4       bne MULT_5                   ; (MOST OF THE TIME WE SHOULD BRANCH)
49DD:  F0 E8       beq MULT_6

;----------------------------------------------------------------------
; DISTANCE HANDLERS
;----------------------------------------------------------------------

RANGE:
; xrefs: $4A01, $4A07, $6431, $6445
; [note] Wrap a 16-bit position difference the short way round the screen
49DF:  C9 10       cmp #$10
49E1:  90 11       bcc RANGE_1                  ; OK
49E3:  C9 F0       cmp #$F0
49E5:  B0 0D       bcs RANGE_1                  ; OK
49E7:  85 15       sta R5                       ; SAVE HI BYTE

RANGE_4:
; xrefs: $4A15
49E9:  A9 00       lda #$00
49EB:  38          sec
49EC:  E5 0C       sbc TEMP2                    ; (TEMP2,A) = 0 - (TEMP2,A)
49EE:  85 0C       sta TEMP2
49F0:  A9 00       lda #$00
49F2:  E5 15       sbc R5

RANGE_1:
; xrefs: $49E1, $49E5, $49F7, $49FB
49F4:  60          rts

RTST:
; xrefs: $48FC, $4912
; [note] RANGE with the difficulty hook: is object X within range?
49F5:  C9 04       cmp #$04                     ; 1/8 SCREEN AWAY
49F7:  90 FB       bcc RANGE_1                  ; NO
49F9:  C9 FC       cmp #$FC
49FB:  B0 F7       bcs RANGE_1
49FD:  A4 DA       ldy BINSCR
49FF:  C0 05       cpy #$05                     ; SCORE>40,000?
4A01:  90 DC       bcc RANGE                    ; NO. BE EASY
4A03:  A4 19       ldy R9
4A05:  C0 03       cpy #$03                     ; MORE THAN 2 ENEMIES?
4A07:  90 D6       bcc RANGE                    ; NO. BE EASY
4A09:  85 15       sta R5                       ; SAVE ACC
4A0B:  8A          txa                          ; GET OBJ INDEX
4A0C:  E0 21       cpx #$21                     ; CHECKING X?
4A0E:  B0 01       bcs RTST_2                   ; NO
4A10:  4A          lsr a

RTST_2:
; xrefs: $4A0E
4A11:  4A          lsr a
4A12:  6A          ror a                        ; PUT X/Y BIT INTO BIT 7
4A13:  45 15       eor R5                       ; GET SIGN OF DIFFERENCE MODIFIED BY X/Y BIT
4A15:  30 D2       bmi RANGE_4                  ; NEGATE DIFFERNECE
4A17:  A5 15       lda R5                       ; RESTORE ACC
4A19:  60          rts                          ; AND EXIT

CPUTD:
; xrefs: $48F9, $490F, $642E, $6442
; [note] 16-bit position difference, object Y minus object X
4A1A:  B9 A5 02    lda OBJXL,y                  ; COMPUTE 16 BIT DIFFERENCE
4A1D:  38          sec
4A1E:  FD A5 02    sbc OBJXL,x
4A21:  85 0C       sta TEMP2
4A23:  B9 63 02    lda OBJXH,y
4A26:  FD 63 02    sbc OBJXH,x
4A29:  60          rts                          ; DONE

SCALER:
; xrefs: $4915, $6448
; [note] Normalise two differences, then take the angle between them
4A2A:  85 14       sta R4                       ; SAVE HIGH Y DIFFERENCE
4A2C:  10 03       bpl SCALER_1
4A2E:  20 EC 70    jsr COMP

SCALER_1:
; xrefs: $4A2C
4A31:  85 15       sta R5                       ; SAVE ABS
4A33:  A5 13       lda R3                       ; GET HI X
4A35:  10 03       bpl SCALER_2
4A37:  20 EC 70    jsr COMP

SCALER_2:
; xrefs: $4A35
4A3A:  05 15       ora R5                       ; MERGE ABS(X) OR ABS(Y)
4A3C:  A2 07       ldx #$07                     ; INITIALIZE X

SCALER_4:
; xrefs: $4A42
4A3E:  0A          asl a                        ; FIND POSITION OF MSB
4A3F:  30 03       bmi SCALER_3
4A41:  CA          dex
4A42:  D0 FA       bne SCALER_4                 ; UNTIL ALL 8 TESTED

SCALER_3:
; xrefs: $4A3F
4A44:  E0 04       cpx #$04                     ; DIRECTION
4A46:  B0 12       bcs SCALER_7                 ; SHIFT LEFT

SCALER_5:
; xrefs: $4A51
4A48:  46 13       lsr R3                       ; SHIFT DIFFERENCE RIGHT N PLACES
4A4A:  66 12       ror R2
4A4C:  46 14       lsr R4
4A4E:  66 0C       ror TEMP2
4A50:  CA          dex
4A51:  10 F5       bpl SCALER_5
4A53:  A6 12       ldx R2                       ; PASS X DIFFERENCE
4A55:  A4 0C       ldy TEMP2                    ; PASS Y DIFFERENCE

SCALER_6:
; xrefs: $4A6B
4A57:  4C D4 70    jmp ATAN

SCALER_7:
; xrefs: $4A46, $4A65
4A5A:  06 12       asl R2                       ; SHIFT DIFFERENCE LEFT UNTIL BIT 15  IS SIGN
4A5C:  26 13       rol R3
4A5E:  06 0C       asl TEMP2
4A60:  26 14       rol R4
4A62:  E8          inx
4A63:  E0 07       cpx #$07
4A65:  90 F3       bcc SCALER_7
4A67:  A6 13       ldx R3                       ; PASS X DIFFERENCE
4A69:  A4 14       ldy R4                       ; PASS Y DIFFERENCE
