START:
; xrefs: $7E69
; [note] Cold start of the game program: INIT, then the frame loop
6000:  20 F5 7B    jsr INIT                     ; INITIALIZE PLAYER 1 FOR START OF GAME
6003:  A5 D4       lda EAFLG                    ; E.A. ROM BUSY ERASING?
6005:  D0 0A       bne START1                   ; YEP. LEAVE IT ALONE
6007:  85 D3       sta EABC                     ; STARTING @
6009:  85 D2       sta EAX
600B:  85 D5       sta EAHSX                    ; INTO HS TABLE
600D:  A9 20       lda #$20                     ; READ COMMAND
600F:  85 D4       sta EAFLG

START1:
; xrefs: $6005, $60FB
; [note] Start a new wave of asteroids, then fall into the frame loop
6011:  20 8E 69    jsr NEWAST                   ; START UP NEW ASTEROIDS

START2:
; xrefs: $6017, $60FE
; [note] The frame loop: wait for the DVG, then run one frame of the game
6014:  2C 02 20    bit HALT                     ; WAIT FOR VG TO FINISH
6017:  30 FB       bmi START2
6019:  20 92 4B    jsr ROTAST                   ; ROTATE THE ASTEROIDS

START2_10:
; xrefs: $601E
601C:  46 75       lsr SYNC                     ; WAIT FOR FRAME SYNCH
601E:  90 FC       bcc START2_10
6020:  A5 76       lda FRAME                    ; SET UP VG BUFFER
6022:  29 01       and #$01                     ; EVEN/ODD
6024:  0A          asl a
6025:  AA          tax
6026:  49 02       eor #$02                     ; FILL THE OTHER ONE
6028:  A8          tay
6029:  BD DE 77    lda RADDR,x                  ; GET 'JMPL' INSTRUCTION
602C:  8D 00 40    sta VECRAM                   ; GIVE IT TO VG
602F:  BD DF 77    lda $77DF,x
6032:  8D 01 40    sta $4001
6035:  B9 DE 77    lda RADDR,y
6038:  0A          asl a
6039:  85 03       sta VGLIST
603B:  B9 DF 77    lda $77DF,y
603E:  2A          rol a
603F:  29 1F       and #$1F                     ; ZAP OFF THE OPCODE
6041:  09 40       ora #$40                     ; MERGE IN 6502 ADDRESS
6043:  85 04       sta $04
6045:  8D 00 30    sta GOADD                    ; START VG
6048:  8D 00 34    sta WTDOG                    ; KICK THE DOG

START2_12:
604B:  E6 76       inc FRAME                    ; NEXT FRAME PLEASE
604D:  D0 3C       bne START2_22
604F:  E6 77       inc $77                      ; COUNT TO 16 BITS
6051:  A5 8B       lda $8B                      ; MSB OF ADDRESS
6053:  09 50       ora #$50                     ; CHECKSUM 5000-5800
6055:  85 11       sta R1
6057:  49 38       eor #$38                     ; CHECKSUM 6800-7000 TOO
6059:  AA          tax
605A:  49 18       eor #$18                     ; CHECKSUM 7000-7800
605C:  85 13       sta R3
605E:  A5 8A       lda PROT                     ; GET LOW ADDRESS
6060:  85 10       sta R0                       ; PUT CHECKSUM ADDRESS IN R0,R1
6062:  85 12       sta R2                       ; ALSO IN R2,R3
6064:  A0 00       ldy #$00                     ; INDEX. ALSO A ZERO FOR LATER
6066:  A5 8D       lda $8D                      ; GET ACCUM
6068:  18          clc
6069:  71 10       adc ($10),y                  ; CS=CS+(5000+N)
606B:  86 11       stx R1
606D:  71 10       adc ($10),y                  ; CS=CS+(6800+N)
606F:  71 12       adc ($12),y                  ; CS=CS+(7000+N)
6071:  69 00       adc #$00                     ; CS=CS+CARRY
6073:  E6 8A       inc PROT                     ; NEXT ADDRESS
6075:  D0 12       bne START2_11                ; NO OVERFLOW
6077:  E6 8B       inc $8B                      ; HIGH ADDRESS
6079:  E0 6F       cpx #$6F                     ; END?
607B:  D0 0C       bne START2_11                ; NOPE
607D:  84 8B       sty $8B                      ; 0 -> HIGH ADDRESS
607F:  49 03       eor #$03                     ; SEED
6081:  85 8C       sta $8C                      ; SIGNAL ERROR OR NOT (S/B 0)
