VGME:
; xrefs: $6B2B
; [note] Display message Y in language A.  VGMSG arrives here with the
;        switch's language; SETROL's copyright line enters here with A=0
;        (English only).  Fetch the language block's address from VGMSGT,
;        add that block's offset for message Y, and TEMP1 now points at
;        the packed text.
7198:  0A          asl a                        ; (SPECIAL ENGLISH ONLY ENTRY POINT)
7199:  AA          tax                          ; 2*LANGUAGE (0,2,4,OR 6)
719A:  BD 36 72    lda $7236,x
719D:  85 0A       sta $0A
719F:  BD 35 72    lda VGMSGT,x                 ; CARRY IS CLEAR FROM ASL ABOVE
71A2:  85 09       sta TEMP1                    ; TEMP1 SETUP NOW
71A4:  71 09       adc ($09),y                  ; RELATIVE ADDRESS TO START OF MESSAGE
71A6:  85 09       sta TEMP1
71A8:  90 02       bcc VGME_10                  ; NO OVERFLOW
71AA:  E6 0A       inc $0A

VGME_10:
; xrefs: $71A8
; [note] The message's screen position: VGMSGS holds an X,Y pair per
;        message number, in beam units over 4 as VGSABS takes them.
;        A = X, X = Y, then fall into CM.
71AC:  98          tya
71AD:  0A          asl a
71AE:  A8          tay
71AF:  B9 19 72    lda VGMSGS,y
71B2:  BE 1A 72    ldx $721A,y

CM:
; xrefs: $7178
; [note] Position the beam at (A,X), emit a WAIT so it settles, then
;        unpack the text at TEMP1 into the display list (falls into ASTMSG).
71B5:  20 31 7A    jsr VGSABS                   ; POSITION BEAM
71B8:  A9 70       lda #$70
71BA:  20 FC 7A    jsr VGWAIT                   ; WAIT FOR BEAM IS

ASTMSG:
; xrefs: $718D, $782B
; [note] Unpack ASCIN-packed text into the display list.  Every two bytes
;        hold three 5-bit character codes: b0 = c1<<3 | c2>>2, and
;        b1 = (c2 & 3)<<6 | c3<<1 | end.  Each code goes to VGMSG1/VGMSG2,
;        which append the glyph's JSRL word.  Stops at the end bit, or
;        early on a code of 0.
71BD:  A0 00       ldy #$00                     ; Y IS INDEX FOR VGLIST
71BF:  A2 00       ldx #$00                     ; X IS INDEX FOR TEMP1

ASTMSG_20:
; xrefs: $71E0
; [note] The loop, one byte pair per pass: code 1 is the top five bits of
;        the first byte; code 2 straddles the two bytes, assembled by the
;        rotate chain; code 3 is bits 5-1 of the second byte, whose bit 0
;        ends the message.
71C1:  A1 09       lda ($09,x)
71C3:  85 0C       sta TEMP2
71C5:  4A          lsr a
71C6:  4A          lsr a                        ; 2*INDEX
71C7:  20 E6 71    jsr VGMSG1                   ; PUT OUT CHARACTER AND UPDATE TEMP1
71CA:  A1 09       lda ($09,x)
71CC:  2A          rol a
71CD:  26 0C       rol TEMP2
71CF:  2A          rol a
71D0:  A5 0C       lda TEMP2
71D2:  2A          rol a
71D3:  0A          asl a
71D4:  20 EC 71    jsr VGMSG2                   ; PUT OUT CHARACTER
71D7:  A1 09       lda ($09,x)
71D9:  85 0C       sta TEMP2
71DB:  20 E6 71    jsr VGMSG1                   ; PUT OUT CHARACTER AND UPDATE TEMP1
71DE:  46 0C       lsr TEMP2
71E0:  90 DF       bcc ASTMSG_20                ; NOT END OF LIST

VGMSG0:
; xrefs: $71F2
; [note] Message done: Y counts the bytes written, VGADD moves VGLIST
;        past them.
71E2:  88          dey
71E3:  4C 67 7A    jmp VGADD                    ; UPDATE VGLIST POINTER

VGMSG1:
; xrefs: $71C7, $71DB
; [note] Step the text pointer TEMP1 (carry into the high byte), then
;        emit the character in A - A is already the code doubled.
71E6:  E6 09       inc TEMP1                    ; UPDATE INDIRECT POINTER TO CHARACTERS
71E8:  D0 02       bne VGMSG2                   ; NO OVERFLOW
71EA:  E6 0A       inc $0A

VGMSG2:
; xrefs: $71D4, $71E8
; [note] Emit one character; A = code*2.  Zero ends the message: the two
;        PLAs drop VGMSG1's return address so the BNE lands in VGMSG0.
;        Codes 1-4 are blank, 0, 1, 2; any other code has 14 added so it
;        indexes A..Z in the VGMSGA JSRL table at $56F8.  In copyright-test
;        mode (CPMTST set) the bytes are checked by CPR.UP, not written.
71EC:  29 3E       and #$3E
71EE:  D0 04       bne VGMSG2_5                 ; NOT END OF LIST
71F0:  68          pla
71F1:  68          pla                          ; PURGE RTS
71F2:  D0 EE       bne VGMSG0                   ; RETURN

VGMSG2_5:
; xrefs: $71EE
; [note] Not the end: map the code to its VGMSGA table index (see VGMSG2).
71F4:  C9 0A       cmp #$0A
71F6:  90 02       bcc VGMSG2_10                ; IF BLANK, 0,1 OR 2
71F8:  69 0D       adc #$0D                     ; SET CORRECT INDEX

VGMSG2_10:
; xrefs: $71F6
; [note] Fetch the glyph's JSRL word from VGMSGA ($56F6+X, X = 2*code or
;        2*code+14) and store both bytes at VGLIST,Y - unless CPMTST says
;        to test them instead.
71FA:  AA          tax
71FB:  BD F6 56    lda $56F6,x                  ; 10. FOR A, 12. FOR B, ....
71FE:  24 90       bit CPMTST                   ; TEST MODE?
7200:  30 0C       bmi VGMSG2_12                ; YEP. GO TEST IT
7202:  91 03       sta ($03),y                  ; PUT JSRL INTO VECTOR LIST
7204:  C8          iny
7205:  BD F7 56    lda $56F7,x
7208:  91 03       sta ($03),y
720A:  C8          iny

VGMSG2_13:
; xrefs: $7217
; [note] Common exit: X back to 0 for the next (TEMP1,X) read.
720B:  A2 00       ldx #$00
720D:  60          rts

VGMSG2_12:
; xrefs: $7200
; [note] Copyright test mode: fold both bytes of the JSRL word into the
;        error flag through CPR.UP instead of storing them.
720E:  20 35 78    jsr CPR.UP
7211:  BD F7 56    lda $56F7,x
7214:  20 35 78    jsr CPR.UP
7217:  D0 F2       bne VGMSG2_13                ; (ALWAYS)

