DASOUN:
; xrefs: $776B
; ---- data $760D-$766C (96 bytes) ----
; [note] PNTRS: 12 sounds x 8 bytes, one per POKEY register ($2C00+n; even
;        n is a channel's frequency AUDF, odd its volume/distortion AUDC).
;        Each byte is that register's envelope offset from SOUND; 0 leaves
;        the register alone.  The sound number the game loads into Y is
;        the entry's offset + 7 (SND.T1 = $07, SND.T2 = $0F, ...).  Decoded
;        row by row (sndtab.py).
760D:  00 00 00 00 00 00 01 08                         ; SND.T1 ($07) thump 1: AUDF4=T16+$01, AUDC4=T17+$08
7615:  00 00 00 00 00 00 0F 08                         ; SND.T2 ($0F) thump 2: AUDF4=T26+$0F, AUDC4=T17+$08
761D:  00 00 00 00 16 21 00 00                         ; SND.LS ($17) little saucer: AUDF3=LS4+$16, AUDC3=LS5+$21
7625:  00 00 2F 36 00 00 00 00                         ; SND.SF ($1F) saucer fire: AUDF2=SF2+$2F, AUDC2=SF3+$36
762D:  3D 44 00 00 00 00 00 00                         ; SND.PF ($27) ship fire: AUDF1=PF0+$3D, AUDC1=PF1+$44
7635:  00 00 00 00 00 00 4B 52                         ; SND.EL ($2F) extra life: AUDF4=EL6+$4B, AUDC4=EL7+$52
763D:  00 00 00 00 28 21 00 00                         ; SND.BS ($37) big saucer: AUDF3=BS4+$28, AUDC3=LS5+$21
7645:  00 00 5D 64 00 00 00 00                         ; SND.DI ($3F) diamond zapped: AUDF2=DI2+$5D, AUDC2=DI3+$64
764D:  00 00 00 00 6F 7A 85 7A                         ; SND.BL ($47) ship back to life: AUDF3=BL4+$6F, AUDC3=BL5+$7A, AUDF4=BL6+$85, AUDC4=BL5+$7A
7655:  90 A5 00 00 00 00 90 B6                         ; SND.HT ($4F) on the high score table: AUDF1=HT0+$90, AUDC1=HT1+$A5, AUDF4=HT0+$90, AUDC4=HT7+$B6
765D:  D3 DE 00 00 00 00 00 00                         ; SND.S ($57) shields: AUDF1=S0+$D3, AUDC1=S1+$DE
7665:  00 00 00 00 00 00 C1 CC                         ; SND.DS ($5F) death star appearance: AUDF4=DS6+$C1, AUDC4=DS7+$CC

SOUND:
; xrefs: $77B2, $77D2
; ---- data $766D-$7751 (229 bytes) ----
; [note] The envelopes.  A sequence is a macro count (1-127; 127 repeats
;        for as long as the sound is allowed to run) then 4-byte steps
;        FCNT,START,CHNG,TOT - every FCNT NMIs add CHNG, TOT times, from
;        START - a 0 ending the repeated group, and 0,0 ending the
;        sequence (the source's REP / STB / SEND / MEND).  CSOUND reads
;        SOUND..SOUND+3,Y.  Decoded row by row (sndtab.py); every step
;        checked against DASOUN.MAC.
766D:  00                                              ; SOUND: offset 0, a register with POINT 0 is free
766E:  01                                              ; T16: repeat 1
766F:  04 E0 03 05                                     ; every 4 NMIs add 3, 5 times, from $E0
7673:  00 00                                           ; end of T16
7675:  01                                              ; T17: repeat 1
7676:  04 A8 FF 05                                     ; every 4 NMIs add -1, 5 times, from $A8
767A:  00 00                                           ; end of T17
767C:  01                                              ; T26: repeat 1
767D:  04 D0 03 05                                     ; every 4 NMIs add 3, 5 times, from $D0
7681:  00 00                                           ; end of T26
7683:  7F                                              ; LS4: repeat 127 (for the whole sound)
7684:  01 04 01 10                                     ; every 1 NMI add 1, 16 times, from $04
7688:  01 14 FF 10                                     ; every 1 NMI add -1, 16 times, from $14
768C:  00 00                                           ; end of LS4
768E:  7F                                              ; LS5: repeat 127 (for the whole sound)
768F:  20 A2 00 01                                     ; every 32 NMIs add 0, 1 time, from $A2
7693:  00 00                                           ; end of LS5
7695:  7F                                              ; BS4: repeat 127 (for the whole sound)
7696:  01 10 01 20                                     ; every 1 NMI add 1, 32 times, from $10
769A:  00 00                                           ; end of BS4
769C:  01                                              ; SF2: repeat 1
769D:  02 0C 01 18                                     ; every 2 NMIs add 1, 24 times, from $0C
76A1:  00 00                                           ; end of SF2
76A3:  01                                              ; SF3: repeat 1
76A4:  10 A4 FF 03                                     ; every 16 NMIs add -1, 3 times, from $A4
76A8:  00 00                                           ; end of SF3
76AA:  01                                              ; PF0: repeat 1
76AB:  01 04 01 40                                     ; every 1 NMI add 1, 64 times, from $04
76AF:  00 00                                           ; end of PF0
76B1:  01                                              ; PF1: repeat 1
76B2:  10 A4 FF 04                                     ; every 16 NMIs add -1, 4 times, from $A4
76B6:  00 00                                           ; end of PF1
76B8:  01                                              ; EL6: repeat 1
76B9:  F0 06 00 02                                     ; every 240 NMIs add 0, 2 times, from $06
76BD:  00 00                                           ; end of EL6
76BF:  0F                                              ; EL7: repeat 15
76C0:  10 A8 00 01                                     ; every 16 NMIs add 0, 1 time, from $A8
76C4:  10 A0 00 01                                     ; every 16 NMIs add 0, 1 time, from $A0
76C8:  00 00                                           ; end of EL7
76CA:  01                                              ; DI2: repeat 1
76CB:  02 50 01 70                                     ; every 2 NMIs add 1, 112 times, from $50
76CF:  00 00                                           ; end of DI2
76D1:  07                                              ; DI3: repeat 7
76D2:  10 A8 00 01                                     ; every 16 NMIs add 0, 1 time, from $A8
76D6:  10 A0 00 01                                     ; every 16 NMIs add 0, 1 time, from $A0
76DA:  00 00                                           ; end of DI3
76DC:  0C                                              ; BL4: repeat 12
76DD:  02 0A 01 03                                     ; every 2 NMIs add 1, 3 times, from $0A
76E1:  04 0C FF 02                                     ; every 4 NMIs add -1, 2 times, from $0C
76E5:  00 00                                           ; end of BL4
76E7:  01                                              ; BL5: repeat 1
76E8:  18 A0 01 05                                     ; every 24 NMIs add 1, 5 times, from $A0
76EC:  18 A5 FF 05                                     ; every 24 NMIs add -1, 5 times, from $A5
76F0:  00 00                                           ; end of BL5
76F2:  18                                              ; BL6: repeat 24
76F3:  02 0A 01 02                                     ; every 2 NMIs add 1, 2 times, from $0A
76F7:  02 0B 00 02                                     ; every 2 NMIs add 0, 2 times, from $0B
76FB:  00 00                                           ; end of BL6
76FD:  10                                              ; HT0: repeat 16
76FE:  0C 21 00 01                                     ; every 12 NMIs add 0, 1 time, from $21
7702:  0C 18 00 01                                     ; every 12 NMIs add 0, 1 time, from $18
7706:  00                                              ; end of the repeated group
7707:  01                                              ; repeat 1
7708:  02 20 10 FF                                     ; every 2 NMIs add 16, 255 times, from $20
770C:  04 30 02 30                                     ; every 4 NMIs add 2, 48 times, from $30
7710:  00 00                                           ; end of HT0
7712:  01                                              ; HT1: repeat 1
7713:  30 21 01 08                                     ; every 48 NMIs add 1, 8 times, from $21
7717:  00                                              ; end of the repeated group
7718:  01                                              ; repeat 1
7719:  80 84 01 04                                     ; every 128 NMIs add 1, 4 times, from $84
771D:  30 85 FF 04                                     ; every 48 NMIs add -1, 4 times, from $85
7721:  00 00                                           ; end of HT1
7723:  04                                              ; HT7: repeat 4
7724:  18 A5 FF 04                                     ; every 24 NMIs add -1, 4 times, from $A5
7728:  18 A1 01 04                                     ; every 24 NMIs add 1, 4 times, from $A1
772C:  00 00                                           ; end of HT7
772E:  10                                              ; DS6: repeat 16
772F:  0C 49 00 01                                     ; every 12 NMIs add 0, 1 time, from $49
7733:  0C 30 00 01                                     ; every 12 NMIs add 0, 1 time, from $30
7737:  00 00                                           ; end of DS6
7739:  02                                              ; DS7: repeat 2
773A:  C0 A4 00 01                                     ; every 192 NMIs add 0, 1 time, from $A4
773E:  00 00                                           ; end of DS7
7740:  01                                              ; S0: repeat 1
7741:  01 F0 01 0F                                     ; every 1 NMI add 1, 15 times, from $F0
7745:  01 FF FF 0F                                     ; every 1 NMI add -1, 15 times, from $FF
7749:  00 00                                           ; end of S0
