774C:  1F A2 00 01                                     ; every 31 NMIs add 0, 1 time, from $A2
7750:  00 00                                           ; end of S1

;----------------------------------------------------------------------
; SOUND STARTER
;----------------------------------------------------------------------

SNDOFF:
; xrefs: $6357, $6830, $775E
; [note] Silence sound Y
7752:  2C 86 77    bit SNDOO_1                  ; SEV (1$=RTS=60)
7755:  18          clc                          ; (THIS MAKES IT EASY LATER)
7756:  90 09       bcc SNDOO_4                  ; (ALWAYS)

SNDPON:
; xrefs: $6690, $6F66
; [note] Start sound Y, but only on idle channels
7758:  38          sec                          ; TURN ON SOUND WITH PRIORITY
7759:  B0 01       bcs SNDOO                    ; (ALWAYS)

SNDON:
; xrefs: $49AD, $63E1, $6865, $6F22, $6F2F, $7038
; [note] Start sound Y, taking its channels over
775B:  18          clc                          ; TURN ON SOUND

SNDOO:
; xrefs: $6584, $7759
; [note] SNDON/SNDPON's shared body; C = priority
775C:  A5 22       lda NPLAYR                   ; ATTRACT MODE?
775E:  F0 F2       beq SNDOFF                   ; YEP. TURN SOUNDS OFF INSTEAD
7760:  B8          clv                          ; BE SURE THE V FLAG IS OFF

SNDOO_4:
; xrefs: $7756
; [note] Walk the eight POKEY registers, X = 7 down to 0, with Y on the
;        sound's PNTRS entry, last byte first (Y arrives as offset + 7).
7761:  8A          txa                          ; SAVE X
7762:  48          pha
7763:  A2 07       ldx #$07                     ; LOOP COUNTER

SNDOO_3:
; xrefs: $7782
; [note] Without priority (C clear) a register whose POINT is busy is left alone.
7765:  90 04       bcc SNDOO_5                  ; GO TURN IT ON
7767:  B5 A2       lda POINT,x                  ; CHANNEL BUSY?
7769:  D0 15       bne SNDOO_6                  ; YEP. LEAVE IT ALONE THEN

SNDOO_5:
; xrefs: $7765
; [note] This register's sequence offset from PNTRS; 0 means the sound does
;        not use it.  V set (SNDOFF) substitutes 0.
776B:  B9 0D 76    lda DASOUN,y                 ; GET OFFSET
776E:  F0 10       beq SNDOO_6                  ; NONE. LEAVE CHANNEL
7770:  50 02       bvc SNDOO_7                  ; NOT TO TURN OFF SOUND
7772:  A9 00       lda #$00                     ; TURN SOUND OFF

SNDOO_7:
; xrefs: $7770
; [note] Hand the register to CSOUND in the order the running NMI needs:
;        POINT = 0 stops whatever was playing, MCOUNT = $80 flags a start,
;        then POINT = the offset.  CSOUND takes it from there.
7774:  48          pha                          ; NMI'S ARE RUNNING SO WE HAVE TO DO THE TURN ON
7775:  A9 00       lda #$00                     ; IN A SPECIFIC ORDER. FIRST WE TURN OFF ANY
7777:  95 A2       sta POINT,x                  ; SOUNDS BY ZAPPING POINT. THEN WE SET 'MCOUNT'
7779:  A9 80       lda #$80                     ; TO '80' TO SIGNAL CSOUND TO START A SOUND.
777B:  95 C2       sta MCOUNT,x                 ; 'MCOUNT' IS NOT DISTURBED UNLESS POINT IS
777D:  68          pla                          ; NOT ZERO. LASTLY WE SET POINT TO THE
777E:  95 A2       sta POINT,x                  ; REQUIRED OFFSET. CSOUND TAKES OVER

SNDOO_6:
; xrefs: $7769, $776E
; FROM HERE
; [note] Next register.
7780:  88          dey                          ; COUNT
7781:  CA          dex                          ; COUNT
7782:  10 E1       bpl SNDOO_3                  ; CONTINUE
7784:  68          pla                          ; RESTORE X AND EXIT
7785:  AA          tax

SNDOO_1:
; xrefs: $7752
; [note] Shared return; SNDOFF also BITs this $60 to set V.
7786:  60          rts

;----------------------------------------------------------------------
; SOUND ROUTINE
;----------------------------------------------------------------------

CSOUND:
; xrefs: $78A6
; [note] Step all eight sound channels; once per NMI
7787:  A2 07       ldx #$07                     ; 8 ITEMS

CSOUND_4:
; xrefs: $77CF
; [note] Per register: idle if POINT is 0.  MCOUNT bit 7 means a sound was
;        just requested - go start it.  Otherwise count FRAMES down; at 0,
;        count COUNT down; at 0 the step is done, else CURRENT += CHNG.
7789:  B4 A2       ldy POINT,x                  ; ANY SOUND?
778B:  F0 3A       beq CSOUND_6                 ; NO
778D:  B5 C2       lda MCOUNT,x                 ; ARE WE TO START ONE?
778F:  30 41       bmi CSOUND_11                ; YES. GO START IT
7791:  D6 B2       dec FRAMES,x                 ; COUNT DOWN TIMER
7793:  D0 34       bne CSOUND_1                 ; CONTINUE
7795:  D6 BA       dec COUNT,x                  ; COUNT DOWN TOTAL COUNTER
7797:  F0 09       beq CSOUND_2                 ; DONE
7799:  B5 AA       lda CURRENT,x                ; CHANGE SOUND
779B:  18          clc
779C:  79 6F 76    adc $766F,y                  ; BY ADDING CHANGE CODE
779F:  4C B0 77    jmp CSOUND_5

CSOUND_2:
; xrefs: $7797
; [note] Step done: Y += 4 to the next STB group.
77A2:  C8          iny                          ; Y=Y+4
77A3:  C8          iny
77A4:  C8          iny
77A5:  C8          iny

CSOUND_7:
; xrefs: $77BD, $77DC
; [note] Load a step: POINT = Y, COUNT = TOT (SOUND+3,Y), CURRENT = START
;        (SOUND+1,Y).
77A6:  94 A2       sty POINT,x
77A8:  B9 70 76    lda $7670,y
77AB:  95 BA       sta COUNT,x                  ; RESET TOTAL COUNTER
77AD:  B9 6E 76    lda $766E,y

CSOUND_5:
; xrefs: $779F
; [note] Store the value, reload FRAMES = FCNT (SOUND,Y).  FCNT 0 is the
;        group terminator: rewind Y to MPNTR and repeat while MCOUNT lasts,
;        else step past the 0 to the next macro count (CSOUND_11).
77B0:  95 AA       sta CURRENT,x                ; RESET VALUE
77B2:  B9 6D 76    lda SOUND,y
77B5:  95 B2       sta FRAMES,x                 ; RESET TIMER
77B7:  D0 10       bne CSOUND_1                 ; CONTINUE
77B9:  B4 CA       ldy MPNTR,x                  ; SET UP Y IN CASE OF RESTART
77BB:  D6 C2       dec MCOUNT,x                 ; MACRO COUNT
77BD:  D0 E7       bne CSOUND_7                 ; RESTART
77BF:  B4 A2       ldy POINT,x
77C1:  C8          iny                          ; SKIP OVER TERM
77C2:  D0 0E       bne CSOUND_11                ; (ALWAYS)

CSOUND_10:
; xrefs: $77D5
; [note] Macro count 0: the sound is over.  Y = 0 goes into POINT and CURRENT.
77C4:  A8          tay                          ; THIS MAKES AN EASY EXIT

CSOUND_8:
; [note] Free the register (POINT = 0).
77C5:  94 A2       sty POINT,x                  ; ZAP THE POINTER

CSOUND_6:
; xrefs: $778B
; [note] Silence it (CURRENT = 0), then write it out.
77C7:  94 AA       sty CURRENT,x                ; ZAP SOUND TOO

CSOUND_1:
; xrefs: $7793, $77B7
; [note] Write CURRENT to POKEY register X; next register; exit after 0.
77C9:  B5 AA       lda CURRENT,x                ; GET SOUND
77CB:  9D 00 2C    sta POKEY,x                  ; WRITE TO POKEY
77CE:  CA          dex                          ; COUNT
77CF:  10 B8       bpl CSOUND_4
77D1:  60          rts                          ; EXIT (FALL THUR TO IDCYC)

CSOUND_11:
; xrefs: $778F, $77C2
; [note] Start, or continue with the next macro: the count at POINT; 0 ends.
77D2:  B9 6D 76    lda SOUND,y                  ; GET COUNT
77D5:  F0 ED       beq CSOUND_10                ; END

CSOUND_9:
; [note] MCOUNT = the count, MPNTR = the first step (for repeats), load it.
77D7:  95 C2       sta MCOUNT,x
77D9:  C8          iny                          ; SKIP UP TO SOUND
77DA:  94 CA       sty MPNTR,x                  ; SAVE POINTER
77DC:  D0 C8       bne CSOUND_7                 ; (ALWAYS)

