;----------------------------------------------------------------------
; DETECT COIN
;----------------------------------------------------------------------

MOOLAH:
; INSTRUCTIONS IN BRACKETS( "[" AND "]" ) ARE FOR ILLUSTRATION ONLY, AND ARE NOT
; ACTUALLY ASSEMBLED.
78A9:  A2 02       ldx #$02                     ; X IS USED TO INDEX FROM RIGHT TO LEFT COIN MECH

$DETCT:
; xrefs: $7937
; [note] Debounce one coin mech
78AB:  BD 00 24    lda $COINA,x
78AE:  0A          asl a
78AF:  B5 9D       lda CNSTT,x
78B1:  29 1F       and #$1F                     ; SHARED INST. SEE BELOW IN BRACKETS []
78B3:  90 37       bcc $DETCT_5                 ; BRANCH IF INPUT LOW (COIN ABSENT)
78B5:  F0 10       beq $DETCT_1                 ; STICK AT 0 (TERMINAL COUNT)
78B7:  C9 1B       cmp #$1B                     ; IN FIRST FIVE SAMPLES?
78B9:  B0 0A       bcs $DETCT_10                ; YES, RUN FAST
78BB:  A8          tay                          ; ELSE SAVE STATUS
78BC:  A5 78       lda INTCT                    ; CHECK INTERUPT CTR
78BE:  29 07       and #$07                     ; ARE D0-D2 ALL ONES?
78C0:  C9 07       cmp #$07                     ; SET CARRY IF SO
78C2:  98          tya                          ; STATUS BACK INTO ACC
78C3:  90 02       bcc $DETCT_1                 ; SKIP IF NOT ALL ONES

$DETCT_10:
; xrefs: $78B9
; [AND I,31.]             ISOLATE COIN-ON DOWN-COUNTER, RESET COIN-OFF UP-CTR.
78C5:  E9 01       sbc #$01                     ; CARRY SET

$DETCT_1:
; xrefs: $78B5, $78C3, $78F4, $78FB
78C7:  95 9D       sta CNSTT,x                  ; SAVE UPDATED STATUS
78C9:  AD 06 20    lda $LAM                     ; CHECK SLAM SWITCH
78CC:  29 80       and #$80
78CE:  F0 04       beq $DETCT_2                 ; BRANCH IF BIT LO (SWITCH OFF)
78D0:  A9 F0       lda #$F0                     ; ELSE SET PRE-COIN SLAM TIMER
78D2:  85 95       sta LMTIM                    ; DECR. 8 TIMES/FRAME=PRST FRAMES

$DETCT_2:
; xrefs: $78CE
78D4:  A5 95       lda LMTIM                    ; CHECK PRE-COIN SLAM TIMER
78D6:  F0 08       beq $DETCT_3                 ; O.K.
78D8:  C6 95       dec LMTIM                    ; ELSE RUN TIMER
78DA:  A9 00       lda #$00
78DC:  95 9D       sta CNSTT,x                  ; CLEAR COIN STATUS
78DE:  95 9A       sta PSTSL,x                  ; CLEAR POST-COIN SLAM-TIMER

$DETCT_3:
; xrefs: $78D6
78E0:  18          clc                          ; DEFAULT "NO COIN DETECTED"
78E1:  B5 9A       lda PSTSL,x                  ; CHECK POST-COIN SLAM-TIMER
78E3:  F0 23       beq $DETCT_8                 ; EMPTY, PROCEED
78E5:  D6 9A       dec PSTSL,x                  ; RUN TIMER
78E7:  D0 1F       bne $DETCT_8                 ; NOT DONE, PROCEED
78E9:  38          sec                          ; WHEN IT BECOMES ZERO, INDICATE A COIN
78EA:  B0 1C       bcs $DETCT_8                 ; (ALWAYS)

$DETCT_5:
; xrefs: $78B3
78EC:  C9 1B       cmp #$1B                     ; IS COIN VALID YET (ON FOR >4 SAMPLES)
78EE:  B0 09       bcs $DETCT_6                 ; NO, RESET IT
78F0:  B5 9D       lda CNSTT,x                  ; GET STATUS AGAIN
78F2:  69 20       adc #$20                     ; BUMP COIN-OFF UP-CTR.
78F4:  90 D1       bcc $DETCT_1                 ; IF IT DIDN'T WRAP, JUST STORE STATUS
78F6:  F0 01       beq $DETCT_6                 ; IT WRAPPED BUT COIN WAS ON TOO LONG, JUST RESET
78F8:  18          clc                          ; SET "VALIDITY" AGAIN

$DETCT_6:
; xrefs: $78EE, $78F6
78F9:  A9 1F       lda #$1F                     ; RESET DOWN-COUNTER
78FB:  B0 CA       bcs $DETCT_1                 ; BRANCH IF COIN TOO LONG OR TOO SHORT
78FD:  95 9D       sta CNSTT,x                  ; SAVE RESET STATUS
78FF:  B5 9A       lda PSTSL,x                  ; CHECK HOWIES ASSUMPTION
7901:  F0 01       beq $DETCT_7                 ; BRANCH IF $PSTSL VACANT
7903:  38          sec                          ; ELSE GIVE CREDIT A LITTLE EARLY

$DETCT_7:
; xrefs: $7901
; [CLC]                   DEFAULT TO "NO COIN" (CARRY IS ALREADY CLEAR)
7904:  A9 78       lda #$78                     ; /(4 COUNTS/FRAME)="POST" FRAMES
7906:  95 9A       sta PSTSL,x                  ; DELAY ACCEPTANCE FOR POST/60 SEC.

$DETCT_8:
; xrefs: $78E3, $78E7, $78EA
7908:  90 2A       bcc $DETCT_9
790A:  A9 00       lda #$00                     ; START WITH 0 (TO ADD 1)
790C:  E0 01       cpx #$01                     ; CHECK WHICH MECH
790E:  90 16       bcc $DETCT_85                ; IF LEFT, ALWAYS ADD 1
7910:  F0 0C       beq $DETCT_83                ; IF CENTER, CHECK HALF-MUL
7912:  A5 94       lda CMODE                    ; GET DOLLAR MUL
7914:  29 0C       and #$0C
7916:  4A          lsr a
7917:  4A          lsr a
7918:  F0 0C       beq $DETCT_85                ; 00-ADD 1
791A:  69 02       adc #$02                     ; ELSE MAP 1,2,3 TO 3,4,5
791C:  D0 08       bne $DETCT_85                ; (ALWAYS)

